import type { PublicImage } from "@/lib/types";

/**
 * An image from the media library: AVIF and WebP variants generated by
 * Laravel, the original as the fallback, positioned on its focal point.
 *
 * `priority` marks the LCP candidate (the hero): fetched early at high
 * priority and decoded with the page. It is in the server HTML, so the
 * preload scanner finds it without a <link rel="preload">, which would fetch
 * the wrong candidate in browsers that pick another format. Every other
 * image loads lazily and decodes off the main thread. The width/height
 * attributes give the box its aspect ratio before the file arrives (CLS);
 * an aspect-* or height class from the caller still wins.
 */
export function Picture({
  image,
  sizes,
  className = "",
  priority = false,
}: {
  image: PublicImage | null | undefined;
  sizes: string;
  className?: string;
  priority?: boolean;
}) {
  if (!image) return null;

  const srcSet = (format: "avif" | "webp") => (image.sources[format] ?? []).map((source) => `${source.url} ${source.width}w`).join(", ");

  return (
    <picture>
      {(["avif", "webp"] as const).map((format) =>
        image.sources[format]?.length ? <source key={format} type={`image/${format}`} srcSet={srcSet(format)} sizes={sizes} /> : null,
      )}
      {/* Optimised by Laravel's media pipeline, so next/image is not used. */}
      <img
        src={image.url}
        alt={image.alt}
        width={image.width ?? undefined}
        height={image.height ?? undefined}
        loading={priority ? "eager" : "lazy"}
        fetchPriority={priority ? "high" : undefined}
        decoding={priority ? undefined : "async"}
        className={className}
        style={{ objectPosition: `${image.focal.x}% ${image.focal.y}%` }}
      />
    </picture>
  );
}
